    for (int k = 1; k <= n - 1; k++) {
        if (k > m) {
            cout << 0;
        } else {
            long long ans = fact[m] * invFact[k] % MOD * invFact[m - k] % MOD;
            cout << ans;
        }
        if (k != n - 1) cout << " ";
    }
    cout << "\n";
    return 0;
}
